  --muted: #9a9387; --rule: #3a3b3f; --rule-2: #2e2f33; --grid: rgba(160, 180, 220, .05);
  --accent: #8db8e8; --accent-ink: #10161d;
  --ok: #6fcf8f; --ok-bg: #1f3426; --warn: #f0b44c; --warn-bg: #3a2d14;
  --bad: #f07d6e; --bad-bg: #40211d; --pivot: #b79cf5; --pivot-bg: #2e2541;
  --neutral: #aaa398; --neutral-bg: #2e2f33;
  --shadow: 0 1px 0 rgba(0,0,0,.3), 0 8px 22px -12px rgba(0,0,0,.7);
  color-scheme: dark;
}

* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0; background-color: var(--paper); color: var(--ink);
  font: 15px/1.55 var(--sans);
  background-image:
    linear-gradient(var(--grid) 1px, transparent 1px),
    linear-gradient(90deg, var(--grid) 1px, transparent 1px);
  background-size: 24px 24px;
  overflow-x: hidden;
}
a { color: var(--accent); text-decoration-thickness: 1px; text-underline-offset: 2px; }
a:hover { text-decoration-thickness: 2px; }
code, .mono, kbd, pre { font-family: var(--mono); font-size: .88em; }
code { background: var(--paper-2); border: 1px solid var(--rule-2); border-radius: 4px; padding: 0 .3em; overflow-wrap: anywhere; }
pre { margin: 0; }
h1, h2, h3 { font-family: var(--serif); font-weight: 600; letter-spacing: -.01em; line-height: 1.2; }
h1 { font-size: 1.9rem; margin: 0 0 .25rem; }
h2 { font-size: 1.3rem; margin: 0 0 .6rem; }
h3 { font-size: 1.05rem; margin: 1rem 0 .4rem; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 3px; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }

/* --- masthead ----------------------------------------------------------------------- */
.masthead { border-bottom: 1px solid var(--rule); background: var(--sheet); position: sticky; top: 0; z-index: 20; }
.masthead .wrap { display: flex; align-items: center; gap: 18px; min-height: 58px; flex-wrap: wrap; }
.brand { display: flex; align-items: baseline; gap: 10px; text-decoration: none; color: var(--ink); white-space: nowrap; }
.brand b { font-family: var(--serif); font-size: 1.25rem; letter-spacing: -.02em; }
.brand b span { color: var(--bad); }
.brand small { font-family: var(--mono); font-size: .72rem; color: var(--muted); }
nav.tabs { display: flex; gap: 2px; flex-wrap: wrap; flex: 1; }
nav.tabs a { color: var(--ink-2); text-decoration: none; padding: 6px 10px; border-radius: 6px; font-size: .92rem; }
nav.tabs a:hover { background: var(--paper-2); }
nav.tabs a[aria-current="page"] { color: var(--ink); background: var(--paper-2); box-shadow: inset 0 -2px 0 var(--ink); }
.mast-tools { display: flex; align-items: center; gap: 10px; }
.live { display: inline-flex; align-items: center; gap: 6px; font: 600 .72rem/1 var(--mono); letter-spacing: .06em; color: var(--muted); text-transform: uppercase; }
.live i { width: 8px; height: 8px; border-radius: 50%; background: var(--ok); box-shadow: 0 0 0 0 var(--ok); animation: pulse 2s infinite; }
.live.off i { background: var(--neutral); animation: none; }
@keyframes pulse { 0% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--ok) 60%, transparent); } 70% { box-shadow: 0 0 0 7px transparent; } 100% { box-shadow: 0 0 0 0 transparent; } }
.btn { font: 600 .85rem/1 var(--sans); border: 1px solid var(--rule); background: var(--sheet); color: var(--ink); padding: 8px 12px; border-radius: 7px; cursor: pointer; text-decoration: none; display: inline-flex; align-items: center; gap: 6px; }
.btn:hover { border-color: var(--ink-2); }
.btn.primary { background: var(--ink); color: var(--paper); border-color: var(--ink); }
.btn.small { padding: 5px 8px; font-size: .78rem; }
.btn[disabled] { opacity: .5; cursor: not-allowed; }
.icon-btn { width: 34px; height: 34px; justify-content: center; padding: 0; }
.ro-badge { font: 600 .7rem/1 var(--mono); padding: 5px 7px; border: 1px dashed var(--muted); color: var(--muted); border-radius: 4px; text-transform: uppercase; letter-spacing: .05em; }

.wrap { max-width: 1240px; margin: 0 auto; padding: 0 16px; }
main.wrap { padding-top: 26px; padding-bottom: 64px; }
.page-head { display: flex; justify-content: space-between; align-items: flex-end; gap: 16px; flex-wrap: wrap; margin-bottom: 22px; }
.page-head p { margin: 0; color: var(--muted); }
.eyebrow { font: 600 .72rem/1 var(--mono); letter-spacing: .12em; text-transform: uppercase; color: var(--muted); margin-bottom: 8px; }
.motto { font-family: var(--serif); font-style: italic; font-size: 1.05rem; color: var(--ink-2); }
.motto::before { content: "“"; } .motto::after { content: "”"; }
.muted { color: var(--muted); }
.small { font-size: .85rem; }

