// NotByDefault UI: theme toggle, copy buttons, live-feed highlighting.
(function () {
  "use strict";
  var root = document.documentElement;

  function store(key, value) {
    try { if (value === null) window.localStorage.removeItem(key); else window.localStorage.setItem(key, value); } catch (e) { /* storage blocked */ }
  }
  function currentTheme() {
    var t = root.getAttribute("data-theme");
    if (t) return t;
    return window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
  }
  function setTheme(t) {
    root.setAttribute("data-theme", t);
    store("nbd-theme", t);
    var b = document.getElementById("theme-toggle");
    if (b) b.setAttribute("aria-label", t === "dark" ? "Switch to light mode" : "Switch to dark mode");
    document.dispatchEvent(new CustomEvent("nbd:theme", { detail: t }));
  }
  window.nbdTheme = currentTheme;

  document.addEventListener("click", function (ev) {
    var t = ev.target.closest("#theme-toggle");
    if (t) { setTheme(currentTheme() === "dark" ? "light" : "dark"); return; }
    var c = ev.target.closest("[data-copy]");
    if (c) {
      ev.preventDefault();
      var text = c.getAttribute("data-copy");
      var done = function () { c.classList.add("done"); setTimeout(function () { c.classList.remove("done"); }, 1400); };
      if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(text).then(done, done);
      else { var a = document.createElement("textarea"); a.value = text; document.body.appendChild(a); a.select(); try { document.execCommand("copy"); } catch (e) {} a.remove(); done(); }
    }
  });

  // Live feed: remember which events were already on screen; flash the new ones.
  var seen = new Set();
  function mark(scope, flash) {
    (scope || document).querySelectorAll("[data-key]").forEach(function (el) {
      var k = el.getAttribute("data-key");
      if (!seen.has(k)) { if (flash) el.classList.add("fresh"); seen.add(k); }
    });
  }
  document.addEventListener("DOMContentLoaded", function () { mark(document, false); });
  document.body && document.body.addEventListener("htmx:afterSwap", function (ev) { mark(ev.target, true); });
  document.addEventListener("htmx:afterSwap", function (ev) { mark(ev.target, true); });

  var live = document.getElementById("live");
  document.addEventListener("htmx:sendError", function () { if (live) live.classList.add("off"); });
  document.addEventListener("htmx:afterRequest", function (ev) {
    if (live && ev.detail && ev.detail.successful) live.classList.remove("off");
  });
})();

{% macro pill(status) -%}
<span class="pill s-{{ status }}">{{ status|status_text }}</span>
{%- endmacro %}

{% macro trace(trace_id, url=None) -%}
{% if trace_id %}<span class="trace"><span class="tag">neatlogs</span><code>{{ trace_id }}</code><button class="btn small copy" type="button" data-copy="{{ trace_id }}" aria-label="Copy trace id {{ trace_id }}">copy</button>{% if url %}<a href="{{ url }}" target="_blank" rel="noopener noreferrer" class="small">open ↗</a>{% endif %}</span>{% else %}<span class="muted">no trace</span>{% endif %}
{%- endmacro %}

{% macro file(rel, label=None) -%}
{% if rel %}<a class="mono small" href="/files/{{ rel }}">{{ label or rel }}</a>{% else %}<span class="muted">-</span>{% endif %}
{%- endmacro %}

{% macro feed(events, empty_text="Run the agent with the hook installed; decisions appear here as they are caught.") -%}
{% if events %}
<ol class="feed">
{% for e in events %}
  <li class="k-{{ e.kind }}" data-key="{{ e.key }}">
    <span class="dot" aria-hidden="true"></span>
    <div class="meta"><span>{{ e.kind|kind_text }}</span><span title="{{ e.at|when }}">{{ e.at|ago }}</span>{% if e.via_ui %}<span class="tag">from the UI</span>{% endif %}</div>
    <div class="title">{% if e.href %}<a href="{{ e.href }}">{{ e.title }}</a>{% else %}{{ e.title }}{% endif %}</div>
    {% if e.detail %}<div class="detail">{{ e.detail }}</div>{% endif %}
    {% if e.effects and e.kind in ("requirement", "pivot", "ui") %}
    <div class="effects"><span class="arrow" aria-hidden="true">→</span>{% for f in e.effects %}<a class="effect" href="{{ f.href }}">{{ pill(f.status) }}{{ f.label }}</a>{% endfor %}</div>
    {% endif %}
    {% if e.trace_id %}<div class="effects">{{ trace(e.trace_id) }}</div>{% endif %}
  </li>
{% endfor %}
</ol>
{% else %}
<div class="empty"><b>No activity yet</b>{{ empty_text }}</div>
{% endif %}
{%- endmacro %}

