      {% for m in into %}<li><span class="tag">← {{ m.edge_type }}</span> <a href="/nodes/{{ m.id }}">#{{ m.id }} {{ m.label }}</a> <span class="muted small">{{ m.type }}</span></li>{% endfor %}
