{% extends "base.html" %}
{% from "_macros.html" import pill, trace, file %}
{% set d = v.d %}{% set data = v.data %}
{% block title %}#{{ d.id }} {{ d.label }}{% endblock %}
{% block content %}
<div class="page-head">
  <div>
    <div class="eyebrow">Receipt · decision #{{ d.id }} · {{ data.kind or "?" }}/{{ data.category or "?" }}</div>
    <h1 class="mono-title">{{ d.label }}</h1>
    <div class="head-flags">{{ pill(v.status) }}
      {% if v.by_default %}<span class="flag">chosen by default</span>{% else %}<span class="flag no">has a why</span>{% endif %}
      {% if data.verdict %}<span class="pill {{ 'ok' if data.verdict == 'keep' else 'warn' if data.verdict == 'switch' else '' }}">verdict: {{ data.verdict }}</span>{% endif %}
    </div>
  </div>
  <a class="btn" href="/graph?focus={{ d.id }}">Show neighbourhood in graph</a>
</div>

<div class="grid-2">
  <article class="receipt" aria-labelledby="h-receipt">
    <h2 id="h-receipt" class="sr-only">Receipt</h2>
    <dl class="kv">
      <dt>Chosen</dt><dd><code>{{ data.chosen or d.label }}</code>{% if data.openrouter_id and data.openrouter_id != data.chosen %} <span class="muted">as</span> <code>{{ data.openrouter_id }}</code>{% endif %}</dd>
      <dt>By</dt><dd>{% if data.tool_name %}an agent's <b>{{ data.tool_name }}</b> tool call{% if data.tool_use_id %} <code class="small">{{ data.tool_use_id }}</code>{% endif %}{% else %}{{ data.source or "recorded by hand" }}{% endif %}</dd>
      {% if data.command %}<dt>Command</dt><dd><code>{{ data.command }}</code></dd>{% endif %}
      {% if data.file %}<dt>Seen in</dt><dd>{{ file(data.file) }}{% if data.evidence %} <span class="muted small">({{ data.evidence }})</span>{% endif %}</dd>{% endif %}
      <dt>When</dt><dd>{{ d.created_at|when }}{% if data.times_seen and data.times_seen > 1 %} <span class="muted small">· seen {{ data.times_seen }}×</span>{% endif %}</dd>
      {% if d.session_id %}<dt>Session</dt><dd><code class="small">{{ d.session_id }}</code></dd>{% endif %}
    </dl>
    <hr>
    <div class="why">
      <div class="eyebrow">Why</div>
      <p class="why-text">{{ v.why }}</p>
      {% if v.cause %}<p class="small">Caused by <a href="/nodes/{{ v.cause.id }}">#{{ v.cause.id }} {{ v.cause.type }}: {{ v.cause.label }}</a>
        {% set src = data.stale_source if v.status == "stale" else data.review_source %}{% if src %} · source: {{ src }}{% endif %}</p>{% endif %}
    </div>
    <hr>
    <dl class="kv sources">
      <dt>Record</dt><dd>{{ file(v.record) }}</dd>
      <dt>Checkpoint</dt><dd>{% if v.record_links and v.record_links.sha %}<a class="mono small" href="{{ v.record_links.link or '#' }}" target="_blank" rel="noopener noreferrer">{{ v.record_links.sha[:12] }} ↗</a>{% if v.record_links.checkpoint %} <span class="tag">checkpoint {{ v.record_links.checkpoint }}</span>{% endif %}{% elif v.record %}<span class="muted small">record not committed yet</span>{% else %}<span class="muted">-</span>{% endif %}</dd>
      <dt>Results</dt><dd>{{ file(v.fit.results if v.fit else None) }}</dd>
      <dt>Trace</dt><dd>{{ trace(v.fit.trace_id if v.fit else None, v.fit.trace_url if v.fit else None) }}</dd>
    </dl>
  </article>
  <aside class="stack">
    {% include "_decision_actions.html" %}
    <section class="sheet">
      <h2>Depends on</h2>
      {% if v.depends %}
      <ul class="plain">{% for n in v.depends %}<li><span class="tag">{{ n.edge_type }}</span> <a href="/nodes/{{ n.id }}">{{ n.label }}</a>{% if n.data.assumption %} <mark class="assume">ASSUMPTION</mark>{% endif %}</li>{% endfor %}</ul>
      {% else %}<p class="muted small">No goal, requirement or constraint linked.</p>{% endif %}
      {% if v.pivots %}<h3>Pivots</h3><ul class="plain">{% for p in v.pivots %}<li>{{ pill(p.data.status or "proposed") }} <a href="/nodes/{{ p.id }}">{{ p.label }}</a></li>{% endfor %}</ul>{% endif %}
    </section>
  </aside>
</div>
{% include "_decision_body.html" %}
{% endblock %}

{% from "_macros.html" import pill, trace, file %}
<div class="section-title"><h2>Call site &amp; affected code</h2><span class="src">Entire Graph · {{ v.affected_source or "touched files" }}{% if data.affected_at %} · {{ data.affected_at|when }}{% endif %}</span></div>
<div class="grid-2">
  <div class="table-wrap">
    {% if v.affected %}
    <table>
      <thead><tr><th>location</th><th>symbol</th><th>how</th></tr></thead>
      <tbody>
      {% for e in v.affected %}
        <tr><td class="mono small">{{ file(e.path, e.path ~ (":" ~ e.line if e.line else "")) }}</td>
            <td class="mono small">{{ e.symbol or "-" }}{% if e.depth %} <span class="tag">caller</span>{% endif %}</td>
            <td class="small">{{ e.via }}</td></tr>
      {% endfor %}
      </tbody>
    </table>
    {% else %}<div class="empty"><b>No code recorded</b>Run <code>notbydefault affected {{ d.id }}</code>.</div>{% endif %}
  </div>
  <div class="sheet">
    {% if v.fit and v.fit.callsite.file %}
    <div class="eyebrow">Call site the fit check tested</div>
    <p class="mono">{{ file(v.fit.callsite.file, v.fit.callsite.file ~ ":" ~ v.fit.callsite.line) }}</p>
    {% if v.fit.callsite.task %}<p class="small">{{ v.fit.callsite.task }}</p>{% endif %}
    {% else %}<p class="muted small">No fit check has located a call site yet.</p>{% endif %}
    {% if v.affected_note %}<p class="small muted">Note: {{ v.affected_note }}</p>{% endif %}
  </div>
</div>

<div class="section-title"><h2>Fit-check evidence</h2>
  <span class="src">{% if v.fit %}{{ file(v.fit.results) }} · run {{ v.fit.run_at|when }}{% else %}no fit check{% endif %}</span></div>
{% if v.fit %}
{% set f = v.fit %}
<div class="table-wrap"><table class="fit">
  <thead><tr>{% for h in f.table.headers %}<th{% if not loop.first %} class="num"{% endif %}>{{ h }}</th>{% endfor %}</tr></thead>
  <tbody>
  {% for r in f.table.rows %}
    <tr class="{{ 'rec' if r.recommended }} {{ 'cur' if r.current }}">
      {% for c in r.cells %}<td class="{{ 'num' if not loop.first }}{{ ' no' if c == 'NO' }}{{ ' yes' if c == 'yes' and loop.last }}">{{ c }}{% if loop.first %}{% if r.recommended %} <span class="pill ok">recommended</span>{% elif r.best %} <span class="pill ok">best quality</span>{% endif %}{% endif %}</td>{% endfor %}
    </tr>
  {% endfor %}
  </tbody>
</table></div>
<div class="grid-2" style="margin-top:16px">
  <div class="receipt">
    <div class="eyebrow">Recommendation</div>
    {% if f.table.refs and f.verdict.recommended %}
    <ol class="recs">
      <li>Cheapest setup that meets the bar: <code>{{ f.verdict.recommended[0] }}{{ " + verifier" if f.verdict.recommended[1] != "alone" }}</code></li>
      <li>Best quality within the budget: {% if f.verdict.best_quality %}<code>{{ f.verdict.best_quality[0] }}{{ " + verifier" if f.verdict.best_quality[1] != "alone" }}</code>{% else %}none fits the budget at this volume{% endif %}</li>
    </ol>
    {% endif %}
    <p>{{ f.verdict.summary }}</p>
    {% if f.verdict.bar %}<p class="small muted">Bar: {{ f.verdict.bar }}.</p>{% endif %}
    {% if f.stopped %}<p class="pill bad">stopped early at --max-cost</p>{% endif %}
    <hr>
    <dl class="kv small">
      <dt>Volume</dt><dd>{{ "{:,.0f}".format(f.assumptions.users or 0) }} users × {{ f.assumptions.calls_per_user }} calls/user/month <mark class="assume">ASSUMPTION</mark></dd>
      <dt>Budget</dt><dd>{{ f.assumptions.budget|money }}/month</dd>
      <dt>Judges</dt><dd class="mono">{{ f.judges|join(", ") }}{% if f.agreement and f.agreement.n %} · agree exactly {{ f.agreement.exact|pct }}, within 1 pt {{ f.agreement.within_1|pct }}{% endif %}</dd>
      <dt>Verifiers</dt><dd>{{ file(f.verifiers) }} <span class="small muted">{{ f.checks|join(", ") }}</span></dd>
      <dt>Prices</dt><dd class="small">{{ f.pricing_source }}{% if f.free_tier %} · <span class="tag">free tier: list-price estimates</span>{% endif %}</dd>
      <dt>Spent</dt><dd class="mono">${{ "%.4f"|format(f.spent or 0) }} · {{ f.requests.made or 0 }} requests, {{ f.requests.cache_hits or 0 }} cache hits</dd>
      <dt>Trace</dt><dd>{{ trace(f.trace_id, f.trace_url) }}</dd>
    </dl>
  </div>
  <div class="sheet">
    <div class="eyebrow">Wrong answers per setup</div>
    {% set any_fail = namespace(v=false) %}
    {% for r in f.table.rows if r.failed_cases %}{% set any_fail.v = true %}
      <p class="small"><b class="mono">{{ r.name }}</b></p>
      <ul class="plain small">{% for case, probs in r.failed_cases.items() %}<li><code>{{ case }}</code> {{ probs[0] if probs else "" }}</li>{% endfor %}</ul>
    {% endfor %}
    {% if not any_fail.v %}<p class="muted small">No per-case failures recorded{{ " (no reference answers)" if not f.table.refs }}.</p>{% endif %}
  </div>
</div>
{% else %}
<div class="empty"><b>Not fit-tested</b>{% if data.kind == "model" %}Run <code>notbydefault check {{ d.id }}</code> to test it against the project's constraints.{% else %}Fit checks test model decisions; this one is a {{ data.kind }} decision.{% endif %}</div>
{% endif %}
{% include "_decision_tail.html" %}

{% from "_macros.html" import pill, trace, file %}
<div class="grid-2">
  <section>
    <div class="section-title"><h2>Rejected alternatives</h2><span class="src">graph: rejects edges</span></div>
    {% if v.rejected %}
    <ul class="ruled">
      {% for a in v.rejected %}
      <li><code>{{ a.label }}</code><div class="small">{{ a.data.reason or "no reason recorded" }}</div>
        {% if a.data.rejected_by_check %}<div class="small muted">by {{ file(a.data.rejected_by_check) }}</div>{% endif %}</li>
      {% endfor %}
    </ul>
    {% else %}<div class="empty"><b>None recorded</b>A fit check records what it rejected and why.</div>{% endif %}
  </section>
  <section>
    <div class="section-title"><h2>Caveats &amp; assumptions</h2><span class="src">{{ file(v.record, "decision record") }} · graph</span></div>
    {% if v.caveats or v.assumption_notes or v.assumptions %}
    <ul class="ruled small">
      {% for c in v.caveats %}<li><span class="tag">caveat</span> {{ c }}</li>{% endfor %}
      {% for n in v.assumptions %}<li><mark class="assume">ASSUMPTION</mark> <a href="/nodes/{{ n.id }}">#{{ n.id }}</a> {{ n.label }}</li>{% endfor %}
      {% for a in v.assumption_notes %}<li>{{ a|md(0) }}</li>{% endfor %}
    </ul>
    {% else %}<div class="empty"><b>None recorded</b></div>{% endif %}
  </section>
</div>

<div class="section-title"><h2>Failure bank</h2><span class="src">{% if v.failures_file %}{{ file(v.failures_file) }} · {{ v.failures_total }} output(s), run first next time{% else %}empty{% endif %}</span></div>
{% if v.failures %}
<div class="table-wrap"><table>
  <thead><tr><th>model</th><th>failed checks</th><th>why</th><th>when</th></tr></thead>
  <tbody>{% for b in v.failures|reverse %}
    <tr><td class="mono small">{{ b.model }}</td><td class="small">{{ (b.failed or [])|join(", ") }}</td>
      <td class="small">{{ (b.reasons or [""])[0] }}</td><td class="mono small">{{ b.at|when }}</td></tr>
  {% endfor %}</tbody>
</table></div>
{% else %}<div class="empty"><b>No failing outputs banked</b>Failing outputs from fit checks are kept here and re-run first.</div>{% endif %}

<div class="section-title"><h2>Resolve</h2><span class="src">{% if v.pr_file %}{{ file(v.pr_file) }}{% else %}<code>notbydefault resolve {{ d.id }}</code>{% endif %}</span></div>
<div id="resolve-result"></div>
{% if v.resolution %}
<div class="receipt">
  <dl class="kv small">
    <dt>Switched</dt><dd><code>{{ v.resolution.from }}</code> → <code>{{ v.resolution.to }}</code></dd>
    <dt>Branch</dt><dd><code>{{ v.resolution.branch }}</code> · {{ v.resolution.at|when }}</dd>
    <dt>Tests</dt><dd>{{ v.resolution.tests }} · verifiers {{ v.resolution.verifiers }}</dd>
    <dt>Trace</dt><dd>{{ trace(v.resolution.trace_id) }}</dd>
  </dl>
  {% if v.pr %}<hr><div class="prose">{{ v.pr|md }}</div>{% endif %}
  {% if v.resolve_diff %}<hr><div class="eyebrow">Diff on {{ v.resolution.branch }}</div>{{ v.resolve_diff|diff }}{% endif %}
</div>
{% elif v.failed_patch %}
<p class="small">The last resolve failed and was rolled back; the undone diff is in {{ file(v.failed_patch) }}.</p>
{% else %}
<p class="muted small">Not resolved yet.{% if not read_only and data.kind == "model" %} Use “Resolve: dry run” above to see the plan and diff without changing anything; applying stays in the CLI (<code>resolve {{ d.id }} --apply</code>).{% endif %}</p>
{% endif %}

{% if v.history %}
<div class="section-title"><h2>Status history</h2><span class="src">graph: decision history</span></div>
<ol class="history">{% for h in v.history %}<li><span class="mono small">{{ h.at|when }}</span> {{ pill(h.status) }} <span class="small">{{ h.event }}</span></li>{% endfor %}</ol>
{% endif %}

