from pathlib import Path
p=Path("notbydefault/ui/app.py"); s=p.read_text(encoding="utf-8")
s=s.replace('''def make_env() -> Environment:''','''def _diff(text: str) -> Markup:
    """A unified diff as escaped lines, coloured by + / - / @@."""
    out = []
    for line in (text or "").splitlines():
        cls = ("add" if line.startswith("+") and not line.startswith("+++") else
               "del" if line.startswith("-") and not line.startswith("---") else
               "hunk" if line.startswith("@@") else "")
        out.append(f'<span class="{cls}">{escape(line)}</span>' if cls else str(escape(line)))
    return Markup('<pre class="code diff">' + "\\n".join(out) + "</pre>")


def make_env() -> Environment:''')
s=s.replace("from jinja2 import Environment, FileSystemLoader, select_autoescape","from jinja2 import Environment, FileSystemLoader, select_autoescape\nfrom markupsafe import Markup, escape")
s=s.replace("env.filters.update(ago=_ago,","env.filters.update(diff=_diff, ago=_ago,")
p.write_text(s,encoding="utf-8")
p=Path("notbydefault/ui/data.py"); s=p.read_text(encoding="utf-8")
s=s.replace('''        "history": list(reversed(data.get("history") or [])),
    }''','''        "history": list(reversed(data.get("history") or [])),
        "resolve_diff": resolve_diff(project, data.get("resolution")),
    }


def resolve_diff(project: Path, res: dict | None) -> str:
    """What a resolve changed on its branch: working tree if checked out, else main...branch."""
    from notbydefault.entire import git
    if not res or not res.get("branch") or not res.get("files"):
        return ""

    def compute():
        branch = git(["rev-parse", "--abbrev-ref", "HEAD"], project)
        if branch == res["branch"]:
            out = git(["diff", "HEAD", "--", *res["files"]], project)
            committed = git(["diff", "HEAD~1", "HEAD", "--", *res["files"]], project)
            return out or committed or ""
        return git(["diff", f"HEAD...{res['branch']}", "--", *res["files"]], project) or ""
    return _cached(("diff", str(project), res["branch"], version(project)), 10.0, compute)''')
p.write_text(s,encoding="utf-8")
EOF
