{% block title %}Timeline{% endblock %}
{% block content %}
<div class="page-head">
  <div>
    <div class="eyebrow">Chronology</div>
    <h1>Cause → effect</h1>
    <p>Decisions caught, hook interrupts, requirement changes, pivots, fit checks and resolves, oldest first.</p>
  </div>
  <div class="legend-kinds small">
    {% for k, label in [("caught","caught"),("hook","hook"),("requirement","requirement"),("pivot","pivot"),("fit_check","fit check"),("resolve","resolve"),("ui","you")] %}
    <span class="lk k-{{ k }}"><i></i>{{ label }}</span>
    {% endfor %}
  </div>
</div>
{% if days %}
{% for day, items in days %}
<section class="day">
  <h2 class="day-head">{{ day }}</h2>
  <ol class="tl">
    {% for e in items %}
    <li class="tl-item k-{{ e.kind }}">
      <time class="tl-time mono" datetime="{{ e.at.isoformat() }}">{{ e.at.astimezone().strftime("%H:%M") }}</time>
      <div class="tl-card">
        <div class="tl-kind">{{ e.kind|kind_text }}{% if e.via_ui %} · from the UI{% endif %}</div>
