"""Decision debt: `notbydefault scan` (and the UI overview).

One point for each:
  unchecked            a decision with no fit check verdict and no reason from a person
  claim false          a claim in an agent's stated reason that the evidence contradicts
  assumption expired   a decision whose verdict rests on an assumption that no longer holds
Read-only: nothing is re-opened here (that is `watch`).
"""
from __future__ import annotations

from pathlib import Path


def unchecked(d: dict) -> bool:
    data = d["data"]
    return not data.get("verdict") and not data.get("reason") \
        and data.get("status", "unreviewed") != "reviewed"


def compute(project: Path, graph, catalog: dict | None = None) -> dict:
    """{"score", "unchecked": [d], "claims_false": [(d, item)], "expired": [(d, [broken])]}"""
    from notbydefault.assumptions import broken
    from notbydefault.fit.providers import load_catalog
    catalog = catalog or load_catalog(project)
    decisions = graph.nodes("decision")
    out = {"unchecked": [d for d in decisions if unchecked(d)], "claims_false": [], "expired": []}
    for d in decisions:
        for item in (d["data"].get("claims") or {}).get("items") or []:
            if item["verdict"] == "false":
                out["claims_false"].append((d, item))
        items = broken(project, graph, d, catalog) \
            or (d["data"].get("assumptions") or {}).get("broken") or []
        if items:
            out["expired"].append((d, items))
    out["score"] = len(out["unchecked"]) + len(out["claims_false"]) + len(out["expired"])
    return out


def scan(project: Path, out=print) -> int:
    from notbydefault.assumptions import describe
    from notbydefault.graph import Graph, db_path
    project = Path(project).resolve()
    if not db_path(project).exists():
        out(f"No Decision Graph at {db_path(project)}.")
        return 1
    with Graph.for_project(project) as g:
        r = compute(project, g)
    out(f"Decision debt: {r['score']} ({len(r['unchecked'])} unchecked, "
        f"{len(r['claims_false'])} claim(s) false, {len(r['expired'])} with expired assumptions)")
    if r["unchecked"]:
        out("\nUnchecked (no fit check, no reason):")
        for d in r["unchecked"]:
            hint = (f"`notbydefault check {d['id']}`" if d["data"].get("kind") == "model"
                    else "give it a reason (UI) or review it")
            out(f"  #{d['id']:<4} {d['label']} [{d['data'].get('kind')}/"
                f"{d['data'].get('category')}] -> {hint}")
    if r["claims_false"]:
        out("\nClaims the evidence contradicts:")
        for d, item in r["claims_false"]:
            out(f"  #{d['id']:<4} {item['type']}: \"{item['text']}\" -> {item['detail']}")
    if r["expired"]:
        out("\nExpired assumptions:")
        for d, items in r["expired"]:
            for b in items:
                out(f"  #{d['id']:<4} {describe(b)}")
    if not r["score"]:
        out("No decision debt.")
    return 0

{% from "_macros.html" import trace, file %}
<div class="grid-2">
<section>
  <div class="section-title"><h2>Claim check</h2><span class="src">{% if v.claims %}{{ v.claims.reason_source }} · split by {{ v.claims.classified_by }} · {{ v.claims.checked_at|when }}{% else %}<code>notbydefault claims {{ d.id }}</code>{% endif %}</span></div>
  {% if v.claims %}
  <blockquote class="agent-reason">“{{ v.claims.reason[:500] }}{{ "…" if v.claims.reason|length > 500 }}”</blockquote>
  {% if v.claims["items"] %}
  <ul class="claims">
    {% for c in v.claims["items"] %}
    <li class="claim v-{{ c.verdict }}">
      <span class="verdict">{{ c.verdict }}</span>
      <div class="claim-body">
        <div><span class="tag">{{ c.type }}</span> “{{ c.text }}”</div>
        <div class="small">{{ c.detail }}</div>
        {% if c.source or c.trace_id %}<div class="small muted">{% if c.source %}{% if c.source.startswith("fit check ") %}{{ file(c.source[10:], c.source) }}{% elif c.source.startswith("http") %}<a href="{{ c.source.split(' ')[0] }}" target="_blank" rel="noopener noreferrer">{{ c.source }}</a>{% else %}{{ c.source }}{% endif %}{% endif %}{% if c.trace_id %} · {{ trace(c.trace_id) }}{% endif %}</div>{% endif %}
      </div>
    </li>
    {% endfor %}
  </ul>
  {% else %}<div class="empty"><b>No claim in the reason</b>The agent gave a reason but it claims nothing checkable.</div>{% endif %}
  {% else %}
  <div class="empty"><b>No stated reason recorded</b>The hook records the agent's own words when it catches a decision; run <code>notbydefault claims {{ d.id }}</code> to check them.</div>
  {% endif %}
</section>
<section>
  <div class="section-title"><h2>Watched assumptions</h2><span class="src">{% if v.watched %}recorded {{ v.watched.recorded_at|when }} · <code>notbydefault watch</code>{% else %}<code>notbydefault watch</code> records them{% endif %}</span></div>
  {% if v.watched and v.watched["items"] %}
  <ul class="ruled small">
    {% for b in v.watched.broken or [] %}
    <li class="broken"><span class="pill bad">broken</span> <b>{{ b.label }}</b>: was {{ b.was|fmtval }}, now {{ b.now|fmtval }} <span class="muted">· broken by {{ b.cause }}</span></li>
    {% endfor %}
    {% set broken_keys = (v.watched.broken or [])|map(attribute="key")|list %}
    {% for i in v.watched["items"] if i.key not in broken_keys %}
    <li><span class="pill ok">holds</span> <b>{{ i.label }}</b>: {{ i.value|fmtval }} <span class="muted">· {{ i.source }}</span></li>
    {% endfor %}
  </ul>
  {% else %}<div class="empty"><b>No assumptions recorded yet</b>A fit check records them; <code>watch</code> records a baseline.</div>{% endif %}
</section>
</div>

